import{_ as s,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const l="/img/math-optimization-logic.svg",g=JSON.parse('{"title":"奥数思维：合理安排，做时间的“魔法师”","description":"同样的几件事，为什么有的人做得快，有的人做得慢？本文带你学习奥数中的“统筹规划”，教你如何通过合理安排顺序，节省宝贵的时间。","frontmatter":{"title":"奥数思维：合理安排，做时间的“魔法师”","date":"2026-02-15T10:00:00.000Z","categories":["数学"],"tags":["小学奥数","统筹规划","最优化问题","逻辑应用"],"description":"同样的几件事，为什么有的人做得快，有的人做得慢？本文带你学习奥数中的“统筹规划”，教你如何通过合理安排顺序，节省宝贵的时间。","cover":"/img/math-optimization-logic.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-olympiad-optimization.md","filePath":"posts/primary-math-olympiad-optimization.md","lastUpdated":null}'),o={name:"posts/primary-math-olympiad-optimization.md"};function e(i,a,r,p,c,h){return n(),t("div",null,[...a[0]||(a[0]=[m('<h1 id="奥数思维-合理安排-做时间的-魔法师" tabindex="-1">奥数思维：合理安排，做时间的“魔法师” <a class="header-anchor" href="#奥数思维-合理安排-做时间的-魔法师" aria-label="Permalink to &quot;奥数思维：合理安排，做时间的“魔法师”&quot;">​</a></h1><p>你有没有遇到过这样的情况：早上起床要刷牙、洗脸、热牛奶、整理书包。如果你一件接一件地做，可能就要迟到了。</p><p>在数学中，研究如何最省时、最省力地完成任务，叫做**“统筹规划”**。掌握了它，你就能像变魔法一样，“偷”出更多的时间。</p><hr><h2 id="一、-核心法宝-能同时做-就别先后做" tabindex="-1">一、 核心法宝：能同时做，就别先后做 <a class="header-anchor" href="#一、-核心法宝-能同时做-就别先后做" aria-label="Permalink to &quot;一、 核心法宝：能同时做，就别先后做&quot;">​</a></h2><p>解决合理安排问题的最高原则是：<strong>利用“等待”的时间，去做别的事情。</strong></p><p><img src="'+l+'" alt="统筹规划对比示意图"></p><p><strong>【经典案例：烧水沏茶】</strong>： 任务清单：</p><ol><li>烧开水（10 分钟）</li><li>洗茶杯（1 分钟）</li><li>拿茶叶（1 分钟）</li><li>沏茶（1 分钟）</li></ol><ul><li><strong>普通做法</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>+</mo><mn>1</mn><mo>+</mo><mn>1</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>1</mn><mn>3</mn></mrow><annotation encoding="application/x-tex">10 + 1 + 1 + 1 = 13</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">3</span></span></span></span>（分钟）。</li><li><strong>聪明做法</strong>：在“烧开水”的 10 分钟里，顺便把“洗茶杯”和“拿茶叶”做了。</li><li><strong>计算</strong>：烧水（10 分钟）+ 沏茶（1 分钟）= <strong>11 分钟</strong>。</li></ul><hr><h2 id="二、-实战模型解析" tabindex="-1">二、 实战模型解析 <a class="header-anchor" href="#二、-实战模型解析" aria-label="Permalink to &quot;二、 实战模型解析&quot;">​</a></h2><h3 id="模型-1-烙饼问题" tabindex="-1">模型 1：烙饼问题 <a class="header-anchor" href="#模型-1-烙饼问题" aria-label="Permalink to &quot;模型 1：烙饼问题&quot;">​</a></h3><p><strong>【例题 1】</strong>：一个锅每次只能烙 2 张饼，每面要烙 3 分钟。烙 3 张饼最快要几分钟？ <strong>解析</strong>：</p><ul><li><strong>方案 A</strong>：先烙 2 张（6 分钟），再烙第 3 张（6 分钟），共 12 分钟。</li><li><strong>方案 B（聪明法）</strong>： <ol><li>烙 1 号和 2 号的正面（3 分钟）。</li><li>拿出 2 号，放入 3 号。烙 1 号背面和 3 号正面（3 分钟）。</li><li>拿出 1 号（熟了），放入 2 号背面。烙 2 号背面和 3 号背面（3 分钟）。 <strong>答案</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mo>+</mo><mn>3</mn><mo>+</mo><mn>3</mn><mo>=</mo><mn>9</mn></mrow><annotation encoding="application/x-tex">3 + 3 + 3 = 9</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">9</span></span></span></span>（分钟）。</li></ol></li></ul><h3 id="模型-2-排队等待问题" tabindex="-1">模型 2：排队等待问题 <a class="header-anchor" href="#模型-2-排队等待问题" aria-label="Permalink to &quot;模型 2：排队等待问题&quot;">​</a></h3><p><strong>【例题 2】</strong>：3 个人去接水，甲接水要 3 分钟，乙要 1 分钟，丙要 5 分钟。怎么排队让所有人等待的总时间最短？ <strong>解析</strong>：</p><ul><li>要想让大家等得少，必须让<strong>速度最快</strong>的人先接。</li><li>顺序：乙（1 分）<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 甲（3 分）<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 丙（5 分）。</li><li><strong>等待总时间</strong>：乙自己不排队；甲等 1 分；丙等 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mo>+</mo><mn>3</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">1+3=4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span> 分。总计 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mo>+</mo><mn>4</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">1+4=5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span> 分。</li></ul><hr><h2 id="三、-进阶技巧-流程图法" tabindex="-1">三、 进阶技巧：流程图法 <a class="header-anchor" href="#三、-进阶技巧-流程图法" aria-label="Permalink to &quot;三、 进阶技巧：流程图法&quot;">​</a></h2><p>面对复杂的安排，可以画一个时间轴流程图。</p><ul><li>把必须按顺序做的（如烧水前必须灌水）连成一线。</li><li>把可以并行的（如烧水时洗杯子）写在下面。</li></ul><hr><h2 id="四、-避坑指南-分清-先后顺序" tabindex="-1">四、 避坑指南：分清“先后顺序” <a class="header-anchor" href="#四、-避坑指南-分清-先后顺序" aria-label="Permalink to &quot;四、 避坑指南：分清“先后顺序”&quot;">​</a></h2><p>有些事情是没法并行的。</p><ul><li>例：没穿袜子不能穿鞋。</li><li>安排时间时，一定要先确定哪些步骤是“前置条件”。</li></ul><hr><h2 id="五、-练一练-时间小管家" tabindex="-1">五、 练一练（时间小管家） <a class="header-anchor" href="#五、-练一练-时间小管家" aria-label="Permalink to &quot;五、 练一练（时间小管家）&quot;">​</a></h2><ol><li><strong>基础关</strong>：小明要洗衣服（自动洗衣机 20 分钟）、扫地（5 分钟）、擦桌子（5 分钟）。他最快多少分钟能做完？</li><li><strong>进阶关</strong>：用平底锅煎鱼，每次只能煎 2 条，每面要煎 2 分钟。煎 5 条鱼最少要几分钟？</li><li><strong>挑战关</strong>：甲、乙、丙三人找医生看病。甲要 10 分钟，乙要 2 分钟，丙要 5 分钟。医生应该按什么顺序看病人，才能使三个病人等候的总时间最少？</li></ol><hr><p><em>总结：合理安排不是为了“赶时间”，而是为了“更高效”。多动脑筋优化流程，你就能成为掌控时间的小主人！</em></p>',31)])])}const u=s(o,[["render",e]]);export{g as __pageData,u as default};
